import{z as i,x as d,o as T,c as B,q as r,j as l,D as e,d as s,s as o,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"DNS 缓存与 TTL","description":"","frontmatter":{"title":"DNS 缓存与 TTL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dns-cache-ttl.md","filePath":"cs/dns-cache-ttl.md","lastUpdated":1791063341000}'),A={name:"cs/dns-cache-ttl.md"};function p(D,a,L,c,h,C){const E=d("Mermaid");return T(),B("div",null,[a[2]||(a[2]=r('<h1 id="dns-缓存与-ttl" tabindex="-1">DNS 缓存与 TTL <a class="header-anchor" href="#dns-缓存与-ttl" aria-label="Permalink to &quot;DNS 缓存与 TTL&quot;">​</a></h1><div class="epigraph"><p>每条记录带着 TTL，解析器与主机按它缓存；TTL 是延迟与一致性的旋钮，不是密码学保证。</p><footer>—— 据 RFC 1034 / 1035；RFC 2308 否定缓存；Kurose and Ross DNS 节整理</footer></div><p>主干<a href="/cs/dns">DNS</a>、<a href="/cs/dns-recursive">递归</a>、<a href="/cs/dns-rr">记录</a> 已给查询链。<a href="/cs/serialization-protobuf">上一课</a> 结束 Web 协议。缺口是<strong>缓存时间</strong>：正缓存、负缓存、过短打根、过长难切换。本课不把 DNSSEC 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每次 URL 都跑迭代会把根打爆，也把 RTT 加进网页。TTL：权威说这份 A 记录能记多久。CDN 用短 TTL 做故障切换；长 TTL 抗 DDoS、减延迟。负缓存（NXDOMAIN）防止缓存穿透。TTL=0 几乎禁用缓存。与 HTTP Cache-Control 同类旋钮，名字空间不同。任播根不靠 TTL 切流量。</p><p><span class="marginnote">术语翻译：TTL（Time To Live）就是记录的保质期，单位秒，由权威服务器随应答下发。解析器存记录时记下剩余时间，有人来问就递减着报；减到 0 就丢弃、重新去问权威。</span></p><p>不要把 TTL 写成证书有效期。</p><p><span class="marginnote">RFC 2308。最小 TTL 与 TTL 上限是解析器政策。本课不把每种 RR 的 TTL 策略写完。</span></p><h3 id="ttl-不是证书期" tabindex="-1">TTL 不是证书期 <a class="header-anchor" href="#ttl-不是证书期" aria-label="Permalink to &quot;TTL 不是证书期&quot;">​</a></h3><p>正负缓存都遵它。短则灵活费查询，长则切得慢。公共解析器让 Geo 变钝。TTL=1s 会打爆权威。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：权威 → 递归缓存 → stub。对照 BGP 收敛：DNS 切换受 TTL 下界约束，常比 BGP 慢或快取决于值。测：看应答里的剩余 TTL。</p><p><span class="marginnote">数字实例：要把网站迁到新 IP，TTL 设 3600 就意味着最长一小时内仍有用户连旧机器。运维惯例是提前 24 小时把 TTL 降到 300，等全网缓存都换上短命记录后再改 A 记录，几分钟完成切换，事后再调回去。</span></p>',13)),(T(),l(n,null,{default:e(()=>[o(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20AUTH%5B%22%E6%9D%83%E5%A8%81%20TTL%22%5D%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E7%BC%93%E5%AD%98%22%5D%0A%20%20REC%20--%3E%20STUB%5B%22%E4%B8%BB%E6%9C%BA%E7%BC%93%E5%AD%98%22%5D%0A%20%20NEG%5B%22NXDOMAIN%22%5D%20--%3E%20NC%5B%22%E8%B4%9F%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"Cookie 会话不替代 DNS 缓存。GeoDNS 下一课用同一 TTL 机制发不同答案。H3 的 HTTPS RR 也有 TTL。过期后要重新查询，无线贵。劫持缓存（没有 DNSSEC）是安全课对象。",-1)),a[5]||(a[5]=t("p",null,"负载均衡用短 TTL 轮询多 A 记录，与 ECMP 不同：在解析器，不在包哈希。",-1)),(T(),l(n,null,{default:e(()=>[o(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22TTL%20%E6%97%8B%E9%92%AE%22%5D%20--%3E%20S%5B%22%E8%B0%83%E7%9F%AD%EF%BC%9A%E5%A6%82%2060%20%E7%A7%92%22%5D%0A%20%20S%20--%3E%20S1%5B%22%E5%88%87%20IP%20%E5%BF%AB%EF%BC%8C%E6%95%85%E9%9A%9C%E5%88%87%E6%8D%A2%E7%81%B5%E6%B4%BB%22%5D%0A%20%20S%20--%3E%20S2%5B%22%E6%9F%A5%E8%AF%A2%E9%87%8F%E5%A4%A7%EF%BC%8C%E6%9D%83%E5%A8%81%E6%89%BF%E5%8E%8B%22%5D%0A%20%20K%20--%3E%20L%5B%22%E8%B0%83%E9%95%BF%EF%BC%9A%E5%A6%82%2086400%20%E7%A7%92%EF%BC%88%E4%B8%80%E5%A4%A9%EF%BC%89%22%5D%0A%20%20L%20--%3E%20L1%5B%22%E6%9F%A5%E8%AF%A2%E5%B0%91%EF%BC%8C%E5%BB%B6%E8%BF%9F%E4%BD%8E%E3%80%81%E6%8A%97%E6%89%93%22%5D%0A%20%20L%20--%3E%20L2%5B%22%E6%94%B9%E5%9C%B0%E5%9D%80%E5%90%8E%E6%97%A7%E8%AE%B0%E5%BD%95%E6%9C%80%E5%A4%9A%E6%BB%9E%E7%95%99%E4%B8%80%E5%A4%A9%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">常见误区：新配的域名立刻收不到邮件，往往不是配置写错，而是之前查到的 NXDOMAIN 被负缓存了——「这个名字不存在」本身也是一条带 TTL 的记录。改完配置要等负缓存过期，或清掉本地缓存再验证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 prefetch 的全部。DNSSEC 是下一课。后课默认：TTL 管 DNS 缓存寿命；切换速度不快于 TTL。</p><p>把所有记录 TTL 设 1 秒会把解析器变成权威的 DDoS 放大器。</p><p>下一课<a href="/cs/dnssec">DNSSEC</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正/负缓存都遵 TTL。</li><li>短 TTL 灵活、费查询；长 TTL 稳、切得慢。</li><li>与 HTTP 缓存同构不同层。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 1034/1035；RFC 2308。</li></ul>',7))])}const f=i(A,[["render",p]]);export{m as __pageData,f as default};
